-- Auth core schema generated by Better Auth 1.7.21 getMigrations().compileMigrations().
CREATE TABLE auth_users (id text NOT NULL PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, emailVerified integer NOT NULL, image text, createdAt date NOT NULL, updatedAt date NOT NULL);
CREATE TABLE auth_sessions (id text NOT NULL PRIMARY KEY, expiresAt date NOT NULL, token text NOT NULL UNIQUE, createdAt date NOT NULL, updatedAt date NOT NULL, ipAddress text, userAgent text, userId text NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE);
CREATE TABLE auth_accounts (id text NOT NULL PRIMARY KEY, accountId text NOT NULL, providerId text NOT NULL, userId text NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE, accessToken text, refreshToken text, idToken text, accessTokenExpiresAt date, refreshTokenExpiresAt date, scope text, password text, createdAt date NOT NULL, updatedAt date NOT NULL);
CREATE TABLE auth_verifications (id text NOT NULL PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expiresAt date NOT NULL, createdAt date NOT NULL, updatedAt date NOT NULL);
CREATE TABLE auth_rate_limits (id text NOT NULL PRIMARY KEY, key text NOT NULL UNIQUE, count integer NOT NULL, lastRequest bigint NOT NULL);
CREATE INDEX auth_sessions_userId_idx ON auth_sessions(userId);
CREATE INDEX auth_accounts_userId_idx ON auth_accounts(userId);
CREATE INDEX auth_verifications_identifier_idx ON auth_verifications(identifier);

CREATE TABLE auth_local_outbox (
  id TEXT PRIMARY KEY,
  recipient TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('verification','recovery')),
  url TEXT NOT NULL,
  created_at TEXT NOT NULL
) STRICT;

CREATE TABLE recipient_snapshots (
  id TEXT PRIMARY KEY,
  wishlist_id TEXT NOT NULL UNIQUE REFERENCES wishlists(id),
  label TEXT NOT NULL CHECK(length(label) BETWEEN 1 AND 100),
  mode TEXT NOT NULL CHECK(mode = 'demo'),
  created_at TEXT NOT NULL,
  UNIQUE(id, wishlist_id)
) STRICT;
INSERT INTO recipient_snapshots
  SELECT lower(hex(randomblob(16))),id,display_names,'demo',created_at FROM wishlists;
CREATE TRIGGER recipient_no_update BEFORE UPDATE ON recipient_snapshots
BEGIN SELECT RAISE(ABORT, 'Recipient snapshots are immutable'); END;
CREATE TRIGGER recipient_no_delete BEFORE DELETE ON recipient_snapshots
BEGIN SELECT RAISE(ABORT, 'Recipient snapshots are immutable'); END;

CREATE UNIQUE INDEX goals_id_wishlist ON goals(id,wishlist_id);
CREATE TABLE contributions (
  id TEXT PRIMARY KEY,
  wishlist_id TEXT NOT NULL REFERENCES wishlists(id),
  goal_id TEXT NOT NULL,
  recipient_snapshot_id TEXT NOT NULL,
  amount_paise INTEGER NOT NULL CHECK(amount_paise BETWEEN 100 AND 10000000),
  currency TEXT NOT NULL CHECK(currency = 'INR'),
  guest_name TEXT NOT NULL CHECK(length(guest_name) <= 100),
  guest_message TEXT NOT NULL CHECK(length(guest_message) <= 500),
  reference TEXT NOT NULL CHECK(length(reference) <= 64),
  status TEXT NOT NULL CHECK(status IN ('reported','needs_review','owner_confirmed','rejected')),
  token_hash TEXT NOT NULL UNIQUE,
  request_hash TEXT NOT NULL,
  token_expires_at TEXT NOT NULL,
  version INTEGER NOT NULL CHECK(version > 0),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  FOREIGN KEY(goal_id,wishlist_id) REFERENCES goals(id,wishlist_id),
  FOREIGN KEY(recipient_snapshot_id,wishlist_id) REFERENCES recipient_snapshots(id,wishlist_id)
) STRICT;
CREATE INDEX contributions_wishlist_created ON contributions(wishlist_id,created_at);
CREATE INDEX contributions_goal_status ON contributions(goal_id,status);
CREATE INDEX contributions_reference ON contributions(wishlist_id,reference);
CREATE TRIGGER contribution_terms_immutable BEFORE UPDATE OF wishlist_id,goal_id,recipient_snapshot_id,
  amount_paise,currency,token_hash,request_hash,token_expires_at,guest_name,guest_message,reference,created_at ON contributions
BEGIN SELECT RAISE(ABORT, 'Contribution terms are immutable'); END;

CREATE TABLE claim_events (
  id TEXT PRIMARY KEY,
  contribution_id TEXT NOT NULL REFERENCES contributions(id),
  actor_id TEXT REFERENCES users(id),
  from_status TEXT,
  to_status TEXT NOT NULL CHECK(to_status IN ('reported','needs_review','owner_confirmed','rejected')),
  confirmed_delta_paise INTEGER NOT NULL,
  reason TEXT NOT NULL CHECK(length(reason) <= 300),
  created_at TEXT NOT NULL
) STRICT;
CREATE INDEX claim_events_contribution ON claim_events(contribution_id);
CREATE TRIGGER claim_events_no_update BEFORE UPDATE ON claim_events
BEGIN SELECT RAISE(ABORT, 'Claim events are append-only'); END;
CREATE TRIGGER claim_events_no_delete BEFORE DELETE ON claim_events
BEGIN SELECT RAISE(ABORT, 'Claim events are append-only'); END;

-- Retire all legacy fictional workspace sessions; the old endpoint no longer grants access.
DELETE FROM sessions;
